  expense_account = v.acct,
  ten99 = v.ten99,
  tax_id = case when coalesce(btrim(c.tax_id), '') = '' then v.tax else c.tax_id end,
  code   = case when coalesce(btrim(c.code), '') = '' then v.vid else c.code end
