-- 3. Review: contacts the lists did not name (set their account by hand).
select type, name, coalesce(nullif(sales_account, ''), nullif(expense_account, ''), '(none)') as account
from contacts
where org_id = (select id from orgs order by created_at limit 1)
  and ((type = 'vendor' and coalesce(expense_account, '') = '') or (type = 'customer' and coalesce(sales_account, '') = ''))
order by type, name;
